import {initialState,move,legalMoves,validState,explain,storeOf,owns} from './engine.js';
import {chooseMove} from './ai.js';
import {puzzles} from './puzzles.js';
import {validSession,settleRound,advanceRound} from './session.js';
import {SPEEDS,animationSteps,treasuryStones,pitStones,createStoneMotion,cancelFlights,rememberPiles,restorePiles} from './animation.js';

const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('mangala.'+key))??fallback;}catch{return fallback;}};
let storageOK=true;
const write=(key,value)=>{try{localStorage.setItem('mangala.'+key,JSON.stringify(value));}catch{storageOK=false;}};
const prefsRaw=read('settings',{});
let prefs={sound:prefsRaw?.sound===true,speed:prefsRaw?.paceVersion===2&&['slow','normal','fast'].includes(prefsRaw?.speed)?prefsRaw.speed:'slow',paceVersion:2};
if(prefsRaw?.paceVersion!==2)write('settings',prefs);
let progress=read('progress',{});if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};
progress.solved=Array.isArray(progress.solved)?[...new Set(progress.solved.filter(i=>Number.isInteger(i)&&i>=1&&i<=18))]:[];
progress.learned=progress.learned===true;
let stats=read('stats',{played:0,won:0,draw:0});if(!stats||['played','won','draw'].some(k=>!Number.isSafeInteger(stats[k])||stats[k]<0))stats={played:0,won:0,draw:0};
let saved=read('session',null);

if(!validSession(saved))saved=null;
let view='home',session=null,state=null,selected=null,busy=false,thinking=false,epoch=0,worker=null,workerTimer=null,previewResult=null,lastMessage='',feedback='',success=false,lesson=0,puzzle=null,attempts=0,replaying=false;
let homeMode='solo',homeSetup={level:'medium',style:'balanced',assisted:true,target:1,names:['Sen','Arkadaşın']};
const levelName={easy:'Rahat',medium:'Odaklı',hard:'Usta'},styleName={balanced:'Dengeli',bold:'Atak',defensive:'Temkinli'};
const lessons=[
 {title:'Bir kuyuyla başla',body:'Alt sıradaki kuyular senin. Bir kuyu seçince taşları alırsın; birini aynı kuyuya bırakır, kalanları sağa doğru dağıtırsın.',goal:'1 numaralı kuyuyu seç, ardından “Hamleyi oyna”ya dokun.',state:initialState(),solution:[0],detail:'Dört taştan biri ilk kuyuda kaldı; diğer üçü sırayla dağıldı. Kuyuda tek taş olsaydı doğrudan sonraki yere giderdi.'},
 {title:'Bir hamle daha',body:'Son taş kendi hazinene düşerse sıra yine sende kalır. Küçük bir hesap, fazladan bir hamle demek.',goal:'Son taşı hazinene ulaştıran kuyuyu bul.',state:initialState(),solution:[3],detail:'4 numaralı kuyu: bir taş yerinde, üç taş yolda. Son taş hazineye düştü; bir kez daha oynarsın.'},
 {title:'Çift sayının gücü',body:'Son taş rakibin kuyusuna düşüp oradaki sayıyı çift yaparsa, o kuyudaki bütün taşları toplarsın.',goal:'Çiftleme kuralıyla en az 6 taş yakala.',puzzleType:'even',detail:'Yalnızca son taşın düştüğü rakip kuyusu değerlendirilir. Diğer kuyulardaki çift sayılar taş kazandırmaz.'},
 {title:'Boş kuyunun fırsatı',body:'Son taş kendi boş kuyuna düşerse, karşı kuyuda taş olduğu sürece hem karşıdakileri hem son taşını toplarsın.',goal:'Boş kuyu kuralıyla en az 6 taş yakala.',puzzleType:'opposite',detail:'Karşı kuyu boş olsaydı son taşın yerinde kalırdı. Bu hamle ek sıra vermez.'},
 {title:'Son taşları kim alır?',body:'Bir oyuncunun altı kuyusu da boşalınca el biter. Kuyularını ilk boşaltan oyuncu, rakip tarafta kalan taşları da alır.',goal:'Tek hamlede eli bitir ve kazan.',puzzleType:'finish',detail:'Mangala’nın önemli inceliği: kalan taşlar, kendi kuyularını ilk boşaltan oyuncuya gider. En çok taşı toplayan kazanır; 24–24 beraberliktir.'}
];
for(const l of lessons)if(l.puzzleType){const p=puzzles.find(p=>p.type===l.puzzleType);l.state=p.state;l.solution=p.solutions;}
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let audioCtx;
function sound(kind='drop'){
 if(!prefs.sound||reduced())return;
 try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(kind==='capture'?620:kind==='win'?780:430+Math.random()*110,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(190,audioCtx.currentTime+.1);g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.13);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.14);}catch{}
}
function announce(text){$('#live').textContent=text;}
function toast(text){$('.notice')?.remove();const n=document.createElement('div');n.className='notice';n.role='status';n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),3500);}
function stopAsync(){epoch++;cancelFlights();busy=false;thinking=false;replaying=false;worker?.terminate();worker=null;clearTimeout(workerTimer);workerTimer=null;}
function saveSession(){if(session){saved=structuredClone(session);write('session',saved);}}
function nav(to){stopAsync();selected=null;previewResult=null;feedback='';success=false;view=to;render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function header(){const active=view==='home'||view==='game'?'home':view==='learn'?'learn':'puzzles';return `<div class="shell"><header class="header"><button class="brand" data-action="nav" data-to="home" aria-label="Mangala ana sayfa"><img src="./icon.svg" alt=""><span class="brand-word">mangala<small>Bir avuç taş, bin hamle</small></span></button><nav class="nav" aria-label="Ana menü"><button class="${active==='home'?'active':''}" data-action="nav" data-to="home">Oyna</button><button class="${active==='learn'?'active':''}" data-action="learn">Öğren</button><button class="${active==='puzzles'?'active':''}" data-action="nav" data-to="puzzles">Bulmacalar</button></nav><div class="header-tools"><button class="icon-btn sound-btn" data-action="sound" aria-label="Sesi ${prefs.sound?'kapat':'aç'}" aria-pressed="${prefs.sound}">${prefs.sound?'♪':'♩'}</button><button class="icon-btn" data-action="settings" aria-label="Ayarlar">⚙</button></div></header></div>`;}
function footer(){return `<footer class="footer"><span>48 taş. İki oyuncu. Her seferinde yeni bir hikâye.</span><span><button data-action="rules">Oyun kuralları</button> · <button data-action="about">Mangala hakkında</button></span></footer>`;}
function pitLabel(i,n){return `${i<6?'Alt':'Üst'} sıra, ${i<6?i+1:i-6} numaralı kuyu, ${n} taş`;}
function ownerName(p){return view==='game'&&session?session.names[p]:p?'Rakip':'Sen';}
function storeName(p){return view==='game'&&session?.mode==='solo'&&p===1?'Rakip':ownerName(p);}
function storeLabel(p,n){return `${ownerName(p)} · ${p?'sol':'sağ'} hazine: ${n} taş`;}
function boardMarkup(board=state?.board||initialState().board,decorative=false){
 const canPlay=!decorative&&!busy&&!thinking&&!success&&!state?.ended&&(view!=='game'||session.mode==='local'||state.turn===0);
 const enabled=canPlay?legalMoves(state):[];
 const preview=decorative?null:previewResult;
 const well=i=>{const col=i<6?i+2:14-i;return `<button class="pit ${i<6?'bottom-pit':'top-pit'} ${enabled.includes(i)?'playable':''} ${selected===i&&!decorative?'selected':''} ${preview?.path.includes(i)?'path-mark':''} ${preview?.last===i?'last-mark':''}" style="grid-column:${col}" data-pit="${i}" ${enabled.includes(i)?'':'disabled'} aria-label="${pitLabel(i,board[i])}" ${decorative?'tabindex="-1" aria-hidden="true"':`aria-pressed="${selected===i}"`}><span class="pit-index" aria-hidden="true">${i<6?i+1:i-6}</span><span class="stone-bed" aria-hidden="true">${pitStones(board[i],i)}</span><span class="pit-number" aria-hidden="true">${board[i]}</span></button>`;};
 const store=(p,cls)=>`<div class="store ${cls}" data-store="${storeOf(p)}" aria-label="${esc(storeLabel(p,board[storeOf(p)]))}"><span class="store-stones" aria-hidden="true">${treasuryStones(board[storeOf(p)],storeOf(p))}</span><span class="store-count">${board[storeOf(p)]}</span><span class="store-owner" title="${esc(ownerName(p))}"><b aria-hidden="true">${p?'◈':'●'}</b><span class="store-name">${esc(storeName(p))}</span></span><span class="store-label">${p?'SOL':'SAĞ'}</span></div>`;
 return `<div class="board ${decorative?'board-home':''}" ${decorative?'aria-hidden="true"':'role="group" aria-label="Mangala oyun tahtası"'}><div class="board-grid">${store(1,'left-store')}${[12,11,10,9,8,7].map(well).join('')}${[0,1,2,3,4,5].map(well).join('')}${store(0,'right-store')}</div><div class="distribution-status" hidden aria-hidden="true"></div></div>`;
}
function paintBoard(board,flash,countsOnly=false){
 for(const p of [0,1]){const score=document.getElementById('score-'+p);if(score)score.textContent=board[storeOf(p)];}
 document.querySelectorAll('[data-pit]').forEach(el=>{const i=Number(el.dataset.pit);if(!countsOnly)el.querySelector('.stone-bed').innerHTML=pitStones(board[i],i);el.querySelector('.pit-number').textContent=board[i];el.setAttribute('aria-label',pitLabel(i,board[i]));el.classList.toggle('falling',i===flash);});
 document.querySelectorAll('[data-store]').forEach(el=>{const i=Number(el.dataset.store);if(!countsOnly)el.querySelector('.store-stones').innerHTML=treasuryStones(board[i],i);el.querySelector('.store-count').textContent=board[i];el.classList.toggle('falling',i===flash);el.setAttribute('aria-label',storeLabel(i===6?0:1,board[i]));});
}
function home(){const n=progress.solved.length;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Kökleri eski. Keyfi hep yeni.</div><h1>Taşlar küçük.<br>Hamleler <em>büyük.</em></h1><p class="lead">Bir avuç taşla düşün, şaşırt, yeniden oyna.<br>Türk Mangala’sında masanın öbür tarafı seni bekliyor.</p><div class="play-setup"><div class="segmented" role="group" aria-label="Oyun modu"><button class="${homeMode==='solo'?'selected':''}" data-action="mode" data-mode="solo" aria-pressed="${homeMode==='solo'}">◉ &nbsp; Bilgisayara karşı</button><button class="${homeMode==='local'?'selected':''}" data-action="mode" data-mode="local" aria-pressed="${homeMode==='local'}">◎ &nbsp; İki kişilik</button></div>${homeMode==='solo'?`<div class="setup-fields"><label class="field"><span>Rakibin seviyesi</span><select id="level">${Object.entries(levelName).map(([v,t])=>`<option value="${v}" ${homeSetup.level===v?'selected':''}>${t}${v==='easy'?' · kolay':v==='medium'?' · orta':' · zor'}</option>`).join('')}</select></label><label class="field"><span>Oyun tarzı</span><select id="style">${Object.entries(styleName).map(([v,t])=>`<option value="${v}" ${homeSetup.style===v?'selected':''}>${t}</option>`).join('')}</select></label></div>`:`<div class="setup-fields"><label class="field"><span>Alt taraftaki oyuncu</span><input id="name0" maxlength="24" value="${esc(homeSetup.names[0])}" autocomplete="off"></label><label class="field"><span>Üst taraftaki oyuncu</span><input id="name1" maxlength="24" value="${esc(homeSetup.names[1])}" autocomplete="off"></label></div>`}<div class="setup-fields"><label class="field"><span>Maç biçimi</span><select id="format"><option value="1" ${homeSetup.target===1?'selected':''}>Tek el</option><option value="2" ${homeSetup.target===2?'selected':''}>Mini turnuva · 2 galibiyet</option></select></label></div><label class="check-field"><input id="assisted" type="checkbox" ${homeSetup.assisted?'checked':''}>Hamle önizlemesi açık${homeMode==='local'?' · iki oyuncu için de':''}</label><div class="start-row"><button class="primary" data-action="new">Masaya otur <span aria-hidden="true">↗</span></button><button class="secondary" data-action="learn">Önce öğren</button></div>${saved&&!saved.state.ended?`<button class="resume" data-action="resume">↳ Yarım kalan oyuna dön · ${saved.state.moves} hamle</button>`:''}</div></div><div class="hero-art"><div class="hero-note">Bir hamlede her şey değişebilir.</div><div class="art-topline"><span><span class="dot"></span>Türk Mangala’sı</span><span>12 kuyu · 48 taş</span></div>${boardMarkup(initialState().board,true)}<div class="board-caption"><span>Taşlarını dağıt. Fırsatları topla.</span><em>Hamle sende.</em></div></div></section><section class="intro-rules" aria-label="Oyunun özü"><div class="rule-snippet"><span class="rule-number">01</span><div><h3>Bir kuyu seç.</h3><p>Taşları sırayla dağıt.<br>Her taş bir sonraki hamleyi değiştirir.</p></div></div><div class="rule-snippet"><span class="rule-number">02</span><div><h3>Son taşı hesapla.</h3><p>Ek sıra kazan, çiftle ya da<br>boş kuyunun fırsatını yakala.</p></div></div><div class="rule-snippet"><span class="rule-number">03</span><div><h3>Hazinen büyüsün.</h3><p>En çok taşı toplayan kazanır.<br>Acele etme, güzel düşün.</p></div></div></section><section class="discovery"><div><div class="eyebrow">Küçük bir zihin molası</div><h2>Bir tahta. Tek doğru hamle.</h2><p>18 kısa strateji bulmacası${n?` · ${n} tanesini çözdün`:', kolay bir başlangıçtan ince hesaplara'}.</p></div><button class="secondary" data-action="nav" data-to="puzzles">Bulmacaları keşfet <span aria-hidden="true">↗</span></button></section>`;}
function playerStrip(p){const actual=view==='game',names=actual?session.names:['Sen','Rakip'];const turn=!state.ended&&state.turn===p;return `<div class="player-strip ${p===0?'bottom':''} ${turn?'is-turn':''}"><div class="player-name"><div class="avatar ${p===0?'teal':''}">${p===0?'●':'◈'}</div><div><strong>${esc(names[p])}</strong><small>${actual&&session.mode==='solo'&&p===1?`← Sol hazine · ${levelName[session.level]}`:p===0?'Alt sıra · sağ hazine →':'← Sol hazine · üst sıra'}${turn?' · sıra sende':''}</small></div></div><div class="score"><span id="score-${p}">${state.board[storeOf(p)]}</span><small>taş</small></div></div>`;}
function controls(){const match=view==='game';return `<div class="action-row"><button class="text-btn" data-action="rules">ⓘ Kurallar</button>${match?`<button class="text-btn" data-action="preview-toggle" ${busy?'disabled':''}>${session.assisted?'◉':'○'} Önizleme ${session.assisted?'açık':'kapalı'}</button>`:''}<button class="text-btn" data-action="speed">◷ ${prefs.speed==='slow'?'Sakin':prefs.speed==='fast'?'Hızlı':'Normal'} animasyon</button></div>`;}
function moveLog(){const recent=session.history.slice(-5).reverse();return `<div class="move-log"><h3>Tahtanın hikâyesi</h3>${recent.length?`<ol>${recent.map((h,i)=>{const r=move(h.before,h.pit);return `<li><span>${session.history.length-i}</span><strong>${esc(session.names[r.player])} · ${r.pit<6?r.pit+1:r.pit-6}</strong><em>${r.extra?'ek sıra':r.gain?`+${r.gain} taş`:'dağıtım'}</em></li>`;}).join('')}</ol>`:`<p class="empty-note">İlk hamleyle birlikte<br>tahtanın hikâyesi burada başlar.</p>`}</div>`;}
function activePanel(){const learning=view==='learn',challenge=view==='puzzle',human=learning||challenge||session.mode==='local'||state.turn===0;
 const title=success?'Güzel hesap!':busy?(replaying?'O hamleye dönüyoruz':'Taşlar yolda…'):thinking?'Rakibin düşünüyor':state.ended?'El tamamlandı':selected!==null?`${selected<6?selected+1:selected-6}. kuyu seçildi`:learning?'Deneyerek öğren':challenge?'Doğru kuyuyu bul':human?`${esc(session.names[state.turn])}, hamle sende`:'Rakibin sırası';
 let instruction=learning?lessons[lesson].goal:challenge?puzzle.goal:lastMessage||'Kendi tarafındaki dolu bir kuyuya dokun. Sonra hamleni onayla.';
 let pre='';if(previewResult){pre=previewResult.extra?'Son taş hazinene düşer. Bir hamle daha kazanırsın.':previewResult.captured?`${previewResult.captured} taş yakalarsın.${previewResult.state.ended?' El de sona erer.':''}`:`${previewResult.path.length} taş dağıtılır. ${previewResult.gain?`Hazinen ${previewResult.gain} taş büyür.`:'Sıra rakibe geçer.'}`;if(previewResult.state.ended)pre+=` Son skor: ${previewResult.state.board[6]}–${previewResult.state.board[13]}.`;}
 return `<div class="turn-box"><div class="eyebrow">${learning?`Adım ${lesson+1} / 5`:challenge?`Bulmaca ${puzzle.id} / 18`:state.ended?'Taşlar toplandı':`Hamle ${state.moves+1}`}</div><h2 class="${thinking?'thinking':''}">${title}</h2><p>${esc(instruction)}</p>${pre?`<div class="preview-note">↳ ${esc(pre)}</div>`:''}${!success&&!state.ended?`<button class="primary" data-action="commit" ${selected===null||busy||thinking||!human?'disabled':''}>Hamleyi oyna <span aria-hidden="true">→</span></button>`:''}${feedback?`<div class="feedback ${success?'success':''}" role="status">${esc(feedback)}</div>`:''}${success?(learning?`<button class="primary" data-action="next-lesson">${lesson===4?'İlk maçına hazırsın ↗':'Sıradaki adım →'}</button>`:`<button class="primary" data-action="next-puzzle">${puzzle.id===18?'Bulmacalara dön':'Sıradaki bulmaca →'}</button>`):learning||challenge?`<div class="lesson-controls"><button class="text-btn" data-action="hint" ${busy?'disabled':''}>Küçük bir ipucu</button><button class="text-btn" data-action="reset-challenge" ${busy?'disabled':''}>Yeniden dene</button></div>`:''}</div>`;
}
function resultPanel(){if(!state.ended)return '';const name=state.winner===null?null:session.names[state.winner],seriesOver=session.wins.some(n=>n>=session.target);let best=null;for(const h of session.history){const r=move(h.before,h.pit);if(!best||r.gain>best.r.gain)best={h,r};}
 return `<section class="result-banner"><div class="eyebrow">${session.target===2?`${session.round}. el tamamlandı`:'Güzel oyundu'}</div><h2>${name?`${esc(name)} kazandı.`:'Denge ustaları: beraberlik.'}</h2><p>${state.board[6]}–${state.board[13]} taş${session.target===2?` · Seri ${session.wins[0]}–${session.wins[1]}`:''}.${session.target===2&&seriesOver?' Mini turnuva tamamlandı.':''}</p>${best?`<div class="highlight">${esc(session.names[best.r.player])}, ${best.r.pit<6?best.r.pit+1:best.r.pit-6}. kuyuyla tek hamlede hazinesine <strong>${best.r.gain} taş</strong> ekledi.<br><button class="text-btn" data-action="replay-best" ${busy?'disabled':''}>↺ Bu hamleyi yeniden izle</button></div>`:''}<div class="start-row"><button class="primary" data-action="next-round" ${busy?'disabled':''}>${session.target===2&&!seriesOver?'Sıradaki el →':'Rövanş ↗'}</button><button class="secondary" data-action="nav" data-to="home" ${busy?'disabled':''}>Ana sayfa</button></div></section>`;
}
function game(){const match=view==='game',learning=view==='learn',title=match?(session.target===2?'Mini turnuva':'Masaya hoş geldin'):learning?'Oynayarak öğren':puzzle.title;return `<div class="game-top"><div><button class="text-btn" data-action="nav" data-to="${view==='puzzle'?'puzzles':'home'}">← ${view==='puzzle'?'Bulmacalar':'Ana sayfa'}</button><h1>${title}</h1></div><span class="pill">${match?(session.mode==='solo'?'Bilgisayara karşı':'Aynı cihazda · 2 kişi'):learning?'Beş küçük adım':'Tek hamlelik keşif'}</span></div>${view==='puzzle'?`<div class="mobile-goal">${esc(puzzle.goal)}</div>`:''}${learning?`<div class="progress-track" aria-label="5 adımdan ${lesson+1}. adım">${lessons.map((_,i)=>`<span class="${i<=lesson?'done':''}"></span>`).join('')}</div>`:''}<div class="game-layout"><div class="table-area">${learning?`<div class="lesson-note"><strong>${lesson+1}. ${lessons[lesson].title}</strong>${lessons[lesson].body}</div>`:''}<p class="rotate-hint"><span aria-hidden="true">↻</span> Daha geniş bir tahta için telefonu yatay çevir.</p>${playerStrip(1)}${boardMarkup()}${playerStrip(0)}<div class="board-legend"><span class="owner-upper">◈ Üst sıra · sol hazine ←</span><span class="owner-lower">● Alt sıra · sağ hazine →</span></div>${controls()}${match&&state.ended?resultPanel():''}${match?`<p class="save-note">${storageOK?'Her hamlede bu tarayıcıya kaydedilir. İstediğin zaman ara verebilirsin.':'Tarayıcı kayda izin vermiyor. Sayfayı kapatırsan bu oyun kaybolabilir.'}</p>`:''}</div><aside class="side-panel">${match&&session.target===2?`<div class="round-score"><span>${session.round}. el · İlk 2 galibiyet</span><strong>${session.wins.join(' – ')}</strong></div>`:''}${activePanel()}${match?moveLog():`<div class="move-log"><h3>${learning?'Bilmek güzel':'Küçük bir not'}</h3><p class="empty-note">${learning?'Bir kuyu seçmek hamleyi yapmaz. Onaylamadan önce fikrini değiştirebilirsin.':'Bu konum gerçek bir oyundan geliyor. Bütün taşlar yerli yerinde; doğru hamle tek. İstediğin kadar deneyebilirsin.'}</p></div>`}</aside></div>`;}
function puzzleList(){const daily=puzzles[(Math.floor((Date.now()-new Date().getTimezoneOffset()*60000)/86400000))%puzzles.length];return `<div class="page-intro"><div><div class="eyebrow">Düşün. Dene. “Buldum!” de.</div><h1>Küçük zihin molaları.</h1><p>Bütün bir maça gerek yok. Bir konuma bak, fırsatı gör.<br>Her bulmacada tek doğru hamle var.</p></div><div class="progress-stat">${progress.solved.length}<span style="color:#aeb6a4"> / 18</span><small>bulmaca çözüldü</small></div></div><section class="challenge-banner"><div><div class="eyebrow">Bugünün seçkisi</div><h2>${daily.title}</h2><p>${daily.goal} Her gün 18 bulmacadan biri öne çıkar.</p></div><button class="primary" data-action="puzzle" data-id="${daily.id}">Bir dakika ayır ↗</button></section>${['İlk kıvılcım','İnce hesap','Son hamlenin gücü'].map((title,g)=>`<section class="puzzle-section"><h2>${title}<span>${g*6+1}–${g*6+6}. bulmacalar</span></h2><div class="puzzle-grid">${puzzles.slice(g*6,g*6+6).map(p=>`<button class="puzzle-card ${progress.solved.includes(p.id)?'solved':''}" data-action="puzzle" data-id="${p.id}"><span class="num">${progress.solved.includes(p.id)?'✓':String(p.id).padStart(2,'0')}</span><div><strong>${p.title}</strong><p>${p.goal}</p><small>${progress.solved.includes(p.id)?'Çözüldü · yeniden oyna':'Tahtayı keşfet ↗'}</small></div></button>`).join('')}</div></section>`).join('')}<div style="height:24px"></div>`;}
function mobileDock(){
 if(!['game','learn','puzzle'].includes(view)||state.ended||success)return '';
 const disabled=selected===null||busy||thinking||(view==='game'&&session.mode==='solo'&&state.turn!==0);
 const text=busy?'Taşlar yolda…':thinking?'Rakibin düşünüyor…':selected===null?'Dolu bir kuyu seç':`${selected<6?selected+1:selected-6}. kuyu${previewResult?.extra?' · ek sıra':previewResult?.captured?` · ${previewResult.captured} taş yakala`:''}`;
 return `<div class="mobile-dock"><div><small>${view==='game'?esc(session.names[state.turn]):'Hamle sende'}</small><strong>${text}</strong></div><button class="primary" data-action="commit" ${disabled?'disabled':''}>Hamleyi oyna →</button></div>`;
}
function render(){document.body.classList.toggle('is-playing',['game','learn','puzzle'].includes(view));const piles=rememberPiles();app.innerHTML=header()+`<main id="main" class="shell ${['game','learn','puzzle'].includes(view)?'playing':''}" tabindex="-1">${view==='home'?home():view==='puzzles'?puzzleList():game()}${footer()}</main>`+mobileDock();restorePiles(piles);}
function readHome(){homeSetup.level=$('#level')?.value||homeSetup.level;homeSetup.style=$('#style')?.value||homeSetup.style;homeSetup.assisted=$('#assisted')?.checked??homeSetup.assisted;homeSetup.target=Number($('#format')?.value||homeSetup.target);if(homeMode==='local')homeSetup.names=[$('#name0')?.value.trim()||'Oyuncu 1',$('#name1')?.value.trim()||'Oyuncu 2'];}
function newSession(){readHome();const start=()=>{stopAsync();session={version:1,state:initialState(),mode:homeMode,level:homeSetup.level,style:homeSetup.style,assisted:homeSetup.assisted,target:homeSetup.target,wins:[0,0],starter:0,round:1,names:homeMode==='solo'?['Sen',`${styleName[homeSetup.style]} rakip`]:homeSetup.names.slice(),history:[],recorded:false};state=session.state;lastMessage='İlk hamle alt sıradaki oyuncunun. Dolu bir kuyu seç.';saveSession();nav('game');};if(saved&&!saved.state.ended)confirmBox('Yeni bir masaya mı?','Yarım kalan oyunun yerine yeni bir oyun kaydedilecek.','Yeni oyun',start);else start();}
function resume(){if(!saved)return;stopAsync();session=structuredClone(saved);state=session.state;lastMessage='Kaldığın yerden devam. Taşlar seni bekledi.';nav('game');scheduleComputer();}
function startLesson(i=0){stopAsync();lesson=i;state=structuredClone(lessons[i].state);selected=null;feedback='';success=false;previewResult=null;view='learn';render();window.scrollTo({top:0,behavior:'instant'});announce(lessons[i].goal);}
function startPuzzle(id){const p=puzzles.find(x=>x.id===id);if(!p)return;stopAsync();puzzle=p;state=structuredClone(p.state);selected=null;previewResult=null;feedback='';success=false;attempts=0;view='puzzle';render();window.scrollTo({top:0,behavior:'instant'});announce(p.goal);}
function selectPit(i){if(busy||thinking||success||state.ended||!legalMoves(state).includes(i)||(view==='game'&&session.mode==='solo'&&state.turn!==0))return;selected=i;feedback='';previewResult=(view==='learn'||view==='game'&&session.assisted)?move(state,i):null;render();document.querySelector(`[data-pit="${i}"]`)?.focus({preventScroll:true});announce(`${i<6?i+1:i-6}. kuyu seçildi. Hamleyi oyna düğmesiyle onayla.`);}
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function animate(result,token){
 const timing=SPEEDS[prefs.speed],steps=animationSteps(result),motion=createStoneMotion();
 const status=text=>{const label=$('.distribution-status');if(label){label.hidden=false;label.textContent=text;}};
 try{
  for(const step of steps){
   if(token!==epoch)return false;
   if(reduced()||document.hidden){motion.dispose();paintBoard(result.state.board);break;}
   if(step.type==='lift'){
    status(`${step.hand+step.board[step.from]} taş: ${step.board[step.from]} kuyuda · ${step.hand} elde`);
    await motion.lift(step.from,step.hand,timing.lift,()=>paintBoard(step.board,undefined,true));
    if(token!==epoch)return false;await pause(timing.hold);continue;
   }
   if(step.type==='transfer'){
    status(step.kind==='sweep'?'Kalan taşlar hazineye…':'Yakalanan taşlar hazineye…');
    await motion.transfer(step.from,step.to,timing.transfer,()=>paintBoard(step.depart,undefined,true));
   }else{
    status(`Elde ${step.hand+1} taş · sıradaki bölmeye`);
    await motion.drop(step.to,timing.travel,timing.flight,()=>status(`${step.hand} elde · 1 taş iniyor`));
   }
   if(token!==epoch)return false;
   paintBoard(step.board,step.to,true);sound(step.type==='transfer'?'capture':'drop');
   if(step.type==='drop')status(step.hand?`Elde ${step.hand} taş · kuyuda ${step.board[step.to]} taş`:result.extra?'Son taş hazinede · bir hamle daha!':'Son taş yerinde');
   await pause(step.type==='transfer'?80:timing.land);
  }
  if(token!==epoch)return false;
  motion.dispose();
  if(!reduced()&&!document.hidden){status(result.state.ended?'Taşlar toplandı':result.extra?'Bir hamle daha!':'Dağıtım tamamlandı');await pause(timing.result);}
  if(token!==epoch)return false;
  const label=$('.distribution-status');if(label)label.hidden=true;
  return true;
 }finally{motion.dispose();}
}
function finishRound(){if(settleRound(session)){if(session.mode==='solo'){stats.played++;if(state.winner===0)stats.won++;if(state.winner===null)stats.draw++;write('stats',stats);}saveSession();}}
async function playPit(pit){if(busy||thinking||state.ended)return;const token=epoch,before=structuredClone(state),result=move(state,pit,true);selected=null;previewResult=null;busy=true;feedback='';
 if(view==='game'){session.history.push({before,pit});session.state=result.state;state=result.state;finishRound();saveSession();}else state=result.state;
 state=before;render();paintBoard(before.board,undefined,true);if(!await animate(result,token))return;state=result.state;busy=false;if(state.ended)sound('win');
 if(view==='game'){lastMessage=`${session.names[result.player]}: ${explain(result).replaceAll('hazinene','hazinesine').replaceAll('kuyuna','kuyusuna').replace('Bir hamle daha senin!','Bir hamle daha kazandı.').replace('topladın.','topladı.')}`;render();announce(`${lastMessage}${state.ended?' El bitti.':` Sıra ${session.names[state.turn]}.`}`);if(state.ended)$('.result-banner')?.scrollIntoView({behavior:reduced()?'instant':'smooth',block:'nearest'});else scheduleComputer();}
 else{attempts++;const correct=(view==='learn'?lessons[lesson].solution:puzzle.solutions).includes(pit);success=correct;if(correct){feedback=view==='learn'?lessons[lesson].detail:`Doğru hamle! ${explain(result)}`;if(view==='puzzle'&&!progress.solved.includes(puzzle.id)){progress.solved.push(puzzle.id);write('progress',progress);}}else{feedback=`${explain(result)} Bu hamle hedefi karşılamadı. Aynı konumda tekrar dene.`;state=structuredClone(view==='learn'?lessons[lesson].state:puzzle.state);}render();announce(feedback);$('.turn-box')?.scrollIntoView({behavior:reduced()?'instant':'smooth',block:'nearest'});}
}
function requestComputer(s){return new Promise(resolve=>{let done=false;const complete=r=>{if(done)return;done=true;clearTimeout(workerTimer);worker?.terminate();worker=null;resolve(r);};try{worker=new Worker(new URL('./ai-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.error)complete(chooseMove(s,'easy',session.style));else complete(data);};worker.onerror=()=>complete(chooseMove(s,'easy',session.style));workerTimer=setTimeout(()=>complete(chooseMove(s,'easy',session.style)),4500);worker.postMessage({id:epoch,state:s,level:session.level,style:session.style});}catch{complete(chooseMove(s,'easy',session.style));}});}
async function scheduleComputer(){if(view!=='game'||session.mode!=='solo'||state.turn!==1||state.ended||busy||thinking)return;const token=epoch;thinking=true;render();const [r]=await Promise.all([requestComputer(structuredClone(state)),pause(reduced()?0:1000)]);if(token!==epoch||view!=='game')return;thinking=false;if(legalMoves(state).includes(r.pit))playPit(r.pit);else {render();toast('Rakip hamlesi hazırlanamadı. Oyunu kaydettik; ana sayfadan devam edebilirsin.');}}
function nextRound(){stopAsync();advanceRound(session);state=session.state;selected=null;previewResult=null;lastMessage=`Bu kez ${session.names[state.turn]} başlıyor.`;saveSession();render();window.scrollTo({top:0,behavior:'instant'});scheduleComputer();}
async function replayBest(){if(busy||!session.history.length)return;stopAsync();const best=session.history.map(h=>({h,r:move(h.before,h.pit,true)})).sort((a,b)=>b.r.gain-a.r.gain)[0],token=epoch;busy=true;replaying=true;render();paintBoard(best.h.before.board);$('.board')?.scrollIntoView({behavior:'smooth',block:'center'});await pause(reduced()?0:650);if(!await animate(best.r,token))return;await pause(reduced()?0:900);if(token!==epoch)return;busy=false;replaying=false;render();announce('Hamle tekrarı bitti. Sonuç tahtası geri geldi.');}
let modalReturnFocus=null,confirmCallback=null;
function openModal(title,html,actions=''){modalReturnFocus=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Pencereyi kapat">×</button></div><div class="modal-body">${html}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;modal.showModal();}
function closeModal(){modal.close();confirmCallback=null;modalReturnFocus?.isConnected&&modalReturnFocus.focus();}
function confirmBox(title,body,label,callback){confirmCallback=callback;openModal(title,`<p>${body}</p>`,`<button class="secondary" data-action="close">Vazgeç</button><button class="primary" data-action="confirm">${label}</button>`);}
function rules(){openModal('Taşların dilini öğren.',`<ol class="rules-list"><li><strong>Dağıt.</strong> Kendi kuyularından birini seç. Bir taşı o kuyuda bırak, kalanları saat yönünün tersine dağıt. Tek taş varsa doğrudan sonraki yere gider. Kendi hazinene uğra; rakibin hazinesini atla.</li><li><strong>Yeniden oyna.</strong> Son taş kendi hazinene düşerse bir hamle daha kazanırsın.</li><li><strong>Çiftle.</strong> Son taş rakibin kuyusundaki sayıyı çift yaparsa o kuyudaki bütün taşları alırsın.</li><li><strong>Boş kuyuyu kullan.</strong> Son taş kendi boş kuyuna düşer ve karşıda taş varsa, son taşınla karşı kuyunun taşlarını birlikte alırsın.</li><li><strong>Sonunu hesapla.</strong> Bir tarafın kuyuları boşalınca el biter. İlk boşaltan oyuncu rakibin kalan taşlarını da alır. En fazla taş kazanır; 24–24 beraberliktir.</li></ol><p class="rule-source">Bu uygulamada oyun süresizdir. Kuyu seçimini hamleyi onaylayana kadar değiştirebilirsin. Bunlar rahat oyun tercihleridir; resmî müsabakanın süre ve dokunulan taşı oynama prosedürü uygulanmaz.<br><a href="https://shgm.gsb.gov.tr/Public/images/SGM/Federasyon/22116mangala.pdf" target="_blank" rel="noopener">Kaynak: Federasyon müsabaka talimatı, Madde 22</a></p>`);}
function settings(){openModal('Senin ritminde.',`<p>Taşların sesi, düşünmenin temposu. Buradaki tercihler bu tarayıcıda saklanır.</p><label class="check-field"><input id="setting-sound" type="checkbox" ${prefs.sound?'checked':''}>Taş sesleri</label><label class="field"><span>Taşların dağıtılma hızı</span><select id="setting-speed"><option value="slow" ${prefs.speed==='slow'?'selected':''}>Sakin · adım adım izle</option><option value="normal" ${prefs.speed==='normal'?'selected':''}>Normal</option><option value="fast" ${prefs.speed==='fast'?'selected':''}>Hızlı · akıcı oyna</option></select></label><p style="font-size:12px">Cihazında hareket azaltma açıksa animasyonları atlarız. Taş renkleri dekoratiftir; kuyu sayıları her zaman görünür.</p><div class="highlight">Bilgisayara karşı ${stats.played} el · ${stats.won} galibiyet · ${stats.draw} beraberlik<br>${progress.solved.length}/18 bulmaca · ${progress.learned?'Öğretici tamamlandı':'Öğretici seni bekliyor'}</div>`,`<button class="primary" data-action="save-settings">Kaydet</button>`);}
document.addEventListener('click',e=>{const pit=e.target.closest('[data-pit]');if(pit&&!pit.disabled){selectPit(Number(pit.dataset.pit));return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
 if(action==='nav'){if(view==='home')readHome();nav(el.dataset.to);}
 else if(action==='mode'){readHome();homeMode=el.dataset.mode;render();}
 else if(action==='new')newSession();
 else if(action==='resume')resume();
 else if(action==='learn')startLesson();
 else if(action==='puzzle')startPuzzle(Number(el.dataset.id));
 else if(action==='commit'&&selected!==null)playPit(selected);
 else if(action==='next-lesson'){if(lesson===4){progress.learned=true;write('progress',progress);homeSetup.level='easy';nav('home');toast('Hazırsın. İlk oyun için rahat seviyeyi seçtik.');}else startLesson(lesson+1);}
 else if(action==='next-puzzle'){if(puzzle.id<18)startPuzzle(puzzle.id+1);else nav('puzzles');}
 else if(action==='reset-challenge'){if(view==='learn')startLesson(lesson);else startPuzzle(puzzle.id);}
 else if(action==='hint'){const sol=view==='learn'?lessons[lesson].solution:puzzle.solutions;selectPit(sol[0]);feedback=`${sol[0]+1}. kuyuyu incele. ${view==='learn'?'Taşların izlediği yol işaretlendi.':'Son taşın nereye düşeceğini saymayı dene.'}`;render();announce(feedback);}
 else if(action==='next-round')nextRound();
 else if(action==='replay-best')replayBest();
 else if(action==='preview-toggle'){if(session.mode==='local')confirmBox('Ortak yardım tercihi',`Hamle önizlemesi iki oyuncu için de ${session.assisted?'kapanacak':'açılacak'}. İkiniz de bu değişikliği kabul ediyor musunuz?`,'Birlikte kabul ediyoruz',()=>{session.assisted=!session.assisted;previewResult=null;selected=null;saveSession();render();});else{session.assisted=!session.assisted;previewResult=null;selected=null;saveSession();render();}}
 else if(action==='sound'){prefs.sound=!prefs.sound;write('settings',prefs);if(prefs.sound)sound();if(!busy)render();}
 else if(action==='speed'){prefs.speed={slow:'normal',normal:'fast',fast:'slow'}[prefs.speed];write('settings',prefs);if(!busy)render();toast(`Animasyon: ${prefs.speed==='slow'?'sakin':prefs.speed==='fast'?'hızlı':'normal'}`);}
 else if(action==='settings')settings();
 else if(action==='save-settings'){prefs.sound=$('#setting-sound').checked;prefs.speed=$('#setting-speed').value;write('settings',prefs);closeModal();if(!busy)render();}
 else if(action==='rules')rules();
 else if(action==='about')openModal('Bir avuç taş, bin hamle.',`<p>Mangala, basit bir tahtada derin düşünmeye alan açan geleneksel bir strateji oyunu. Bu sürüm, Türk Mangala’sının altı kuyulu, 48 taşlı kurallarını temel alır.</p><p>Bilgisayar rakibi cihazında hesap yapar. Oyun hesabı ve ücretli yapay zekâ servisi gerekmez. İki kişilik mod aynı cihazda oynanır.</p><p>Oyunlar ve ilerleme bu tarayıcıda tutulur; tarayıcı verilerini silmek bunları da siler. Sesler ve görseller uygulamanın içinde üretilir.</p><p><a href="https://github.com/Gokhanagingil/mandala" target="_blank" rel="noopener">Kaynak kodu ↗</a> · Sürüm 1.3</p>`);
 else if(action==='close')closeModal();
 else if(action==='confirm'){const cb=confirmCallback;closeModal();cb?.();}
});
modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
modal.addEventListener('cancel',()=>{confirmCallback=null;});
let narrow=innerWidth<=480;window.addEventListener('resize',()=>{const changed=narrow!==(innerWidth<=480);narrow=innerWidth<=480;if(changed&&!busy)render();});
document.addEventListener('keydown',e=>{if(modal.open||busy||thinking||e.target.matches('input,select,textarea'))return;if((view==='game'||view==='learn'||view==='puzzle')&&/^[1-6]$/.test(e.key)){const i=Number(e.key)-1+(state.turn===1?7:0);selectPit(i);}if(e.key==='Enter'&&selected!==null&&e.target.closest('[data-pit]')){e.preventDefault();playPit(selected);}});
render();
